func (c *current) onEscape1(cc any) (any, error) {
	switch AnyValToType[byte]("Escape.c", cc) {
	case 'n':
		return []byte{'\n'}, nil
	case 'r':
		return []byte{'\r'}, nil
	case 't':
		return []byte{'\t'}, nil
	case '"':
		return []byte{'"'}, nil
	case '\\':
		return []byte{'\\'}, nil
	}
	return nil, fmt.Errorf("invalid escape")
}

